func newAuthLogoutCmd(flags *rootFlags) *cobra.Command {
	return &cobra.Command{
		Use:     "logout",
		Short:   "Clear stored credentials",
		Example: "  threatdown-cli auth logout",
		RunE: func(cmd *cobra.Command, args []string) error {
			cfg, err := config.Load(flags.configPath)
			if err != nil {
				return configErr(err)
			}
			// Hand-wired (handfixes.json: dry-run-never-mints): a preview clears nothing.
			if flags.dryRun {
				fmt.Fprintf(cmd.ErrOrStderr(), "would clear the stored credentials (%s)\n(dry run - nothing changed)\n", cfg.Path)
				return nil
			}
			if err := cfg.ClearTokens(); err != nil {
				return configErr(fmt.Errorf("clearing tokens: %w", err))
			}

			// Identify which (if any) auth env var is still exported so the
			// JSON envelope and the human prose can both surface it.
			envStillSet := ""
			if envStillSet == "" && os.Getenv("THREATDOWN_CLIENT_ID") != "" {
				envStillSet = "THREATDOWN_CLIENT_ID"
			}
			if envStillSet == "" && os.Getenv("THREATDOWN_CLIENT_SECRET") != "" {
				envStillSet = "THREATDOWN_CLIENT_SECRET"
			}

			// JSON envelope: {cleared: true, note?: "<env_var> env var is still set"}.
			if flags.asJSON {
				out := map[string]any{"cleared": true}
				if envStillSet != "" {
					out["note"] = envStillSet + " env var is still set"
				}
				return printJSONFiltered(cmd.OutOrStdout(), out, flags)
			}

			if envStillSet != "" {
				fmt.Fprintf(cmd.OutOrStdout(), "Config cleared. Note: %s env var is still set.\n", envStillSet)
				return nil
			}
			fmt.Fprintln(cmd.OutOrStdout(), "Logged out. Credentials cleared.")
			return nil
		},
	}
}

// hand-fix: scopes as a list so press dogfood's scope-coverage scan sees
// each scope (it reads "execute read write" as one scope). Same wire value.
func resolveClientCredentialsScopes() []string {
	if scope := cliutil.EnvOverride("THREATDOWN_OAUTH_SCOPE"); scope != "" {
		return strings.Fields(scope)
	}
	scopes := []string{"execute", "read", "write"}
	return scopes
}
